"""Generate static pages from the shared EN/AR/RU source copy. No frontend build dependency."""
from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parents[1]
HOME=json.loads((ROOT/'assets/translations.json').read_text())['en']
KIT=json.loads((ROOT/'media-kit/translations.json').read_text())['en']
DATA=json.loads((ROOT/'media-kit/data.json').read_text())
MAIL='mailto:ali@alialkhuzaee.com?subject=Brand%20Partnership%20Inquiry%20%E2%80%94%20Ali%20Alkhuzaee'
NOTION='https://fluorescent-pull-571.notion.site/Public-Portfolio-394cb7f2498180f78054e85fb41bdec4?source=copy_link'
def t(k,tag='span',cls='',kit=False):
 c=KIT if kit else HOME
 return f'<{tag} class="{cls}" data-i18n="{k}">{e(c[k])}</{tag}>'
def arr(k,value,tag='span'):return f'<{tag} data-array="{k}">{e(value)}</{tag}>'
def button(k,url,kind='primary',kit=False,route=False):return f'<a class="btn {kind}" href="{e(url)}"'+(' data-language-route' if route else '')+(' download="Ali-Alkhuzaee-Media-Kit.pdf"' if '.pdf' in url else '')+'>'+t(k,kit=kit)+'<span aria-hidden="true">↗</span></a>'
def sectionhead(label,title,accent='',intro='',kit=False):
 return '<div class="section-heading reveal">'+t(label,'p','eyebrow',kit)+'<div class="heading-row"><h2>'+t(title,kit=kit)+(t(accent,'em') if accent else '')+'</h2>'+(t(intro,'p','section-intro',kit) if intro else '')+'</div></div>'
def orb():return '<div class="orb-scene" aria-hidden="true"><div class="orb-halo"></div><div class="orb-core"></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><span class="spark">✦</span></div>'
def picture(kind):
 sizes='(max-width: 760px) 80vw, 36vw'
 if kind=='hero':return f'<img class="hero-photo" src="/assets/portraits/ali-hero-690.webp?v=2" srcset="/assets/portraits/ali-hero-420.webp?v=2 420w, /assets/portraits/ali-hero-690.webp?v=2 440w" sizes="{sizes}" width="440" height="1201" data-alt="portraitAlt" alt="Ali Alkhuzaee in a navy suit" fetchpriority="high">'
 return f'<img class="partnership-photo" src="/assets/portraits/ali-partnership-900.webp?v=2" srcset="/assets/portraits/ali-partnership-480.webp?v=2 480w, /assets/portraits/ali-partnership-900.webp?v=2 900w" sizes="{sizes}" width="900" height="900" data-alt="partnershipAlt" alt="Ali Alkhuzaee pointing towards the partnership message" fetchpriority="high">'
def nav(kit):
 return '<header class="site-header"><div class="nav-shell"><a class="brand" href="/" data-language-route aria-label="Ali Alkhuzaee home"><span class="brand-mark" aria-hidden="true">A<span>✦</span></span><span>ALI <b>ALKHUZAEE</b></span></a><nav class="main-nav" id="main-nav" aria-label="Main navigation">'+''.join(f'<a href="/{"" if kit else ""}#{id}" data-language-route>'+t(k)+'</a>' for k,id in [('navAbout','about'),('navExpertise','expertise'),('navWork','work')])+'<a href="/products/" data-language-route>'+t('navProducts')+'</a>'+f'<a class="nav-partnership" href="/media-kit/" data-language-route'+(' aria-current="page"' if kit else '')+'>'+t('navPartnerships')+'</a></nav><div class="nav-tools"><label class="sr-only" for="language" data-i18n="language">Choose language</label><select id="language"><option value="en">EN</option><option value="ar">العربية</option><option value="ru">RU</option></select><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false" aria-label="Open navigation" data-label="menu"><span></span><span></span></button></div></div></header>'
# Thumbnail chain for click-to-play Shorts. Inline so it works before the deferred script loads:
# skip YouTube's 120x90 "missing size" placeholder, then fall back to the next size, then to the titled poster.
THUMB_ERROR="var n=(this.dataset.next||'').split(' ').filter(Boolean);if(n.length){this.dataset.next=n.slice(1).join(' ');this.src=n[0]}else{this.hidden=true}"
THUMB_LOAD="if(this.naturalWidth<=120){this.onerror()}else{this.closest('.short-poster').style.setProperty('--thumb','url('+this.currentSrc+')');this.dataset.loaded=this.naturalWidth+'x'+this.naturalHeight}"
def videos():
 cards=[]
 for i,v in enumerate(DATA['work']):
  if v.get('embed'):
   # Click-to-play Short: a plain YouTube link until JavaScript swaps in the privacy-enhanced player on request.
   local=[f'/assets/media-kit/{v["id"]}.{ext}' for ext in ('webp','jpg') if (ROOT/f'assets/media-kit/{v["id"]}.{ext}').exists()]
   thumbs=local[:1]+v['thumbnails']
   cards.append(f'<article class="work-card short-card reveal" data-embed="{e(v["embed"])}"><div class="thumbnail"><a class="short-poster" href="{e(v["url"])}" target="_blank" rel="noopener noreferrer" data-short-play="{i}" aria-label="{e(HOME["playVideo"]+": "+v["title"]["en"])}"><span class="short-fallback" aria-hidden="true">{e(v["title"]["en"])}</span><span class="short-cover"><img src="{e(thumbs[0])}" data-next="{e(" ".join(thumbs[1:]))}" alt="" width="1080" height="1920" loading="lazy" decoding="async" referrerpolicy="no-referrer" onload="{THUMB_LOAD}" onerror="{THUMB_ERROR}"></span><span class="play" aria-hidden="true">▶</span><span class="video-badge">YouTube Shorts</span></a></div><div class="work-text">'+arr(f'workTopics.{i}',HOME['workTopics'][i],'small')+f'<h3 data-video-title="{i}">{e(v["title"]["en"])}</h3><p class="work-desc" data-video-desc="{i}">{e(v["description"]["en"])}</p><a class="short-link" href="{e(v["url"])}" target="_blank" rel="noopener noreferrer">'+t('openYouTube')+' <span aria-hidden="true">↗</span></a></div></article>')
   continue
  cards.append(f'<a class="work-card reveal" href="{e(v["url"])}" target="_blank" rel="noopener noreferrer"><div class="thumbnail"><img src="/assets/media-kit/{v["id"]}.webp" alt="{e(v["title"]["en"])} — Ali Alkhuzaee" width="480" height="360" loading="lazy"><span class="play" aria-hidden="true">↗</span><span class="video-badge">YouTube Shorts</span></div><div class="work-text">'+arr(f'workTopics.{i}',HOME['workTopics'][i],'small')+f'<h3 data-video-title="{i}">{e(v["title"]["en"])}</h3>'+t('watch')+' <span aria-hidden="true">↗</span></div></a>')
 return '<section class="section paper" id="work"><div class="shell">'+sectionhead('workLabel','workTitle','workAccent','workIntro')+'<div class="works">'+''.join(cards)+'</div></div></section>'
def international():
 return '<section class="section navy international" id="international"><div class="shell global-grid"><div class="reveal">'+t('internationalLabel','p','eyebrow')+'<h2>'+t('globalTitle')+t('internationalAccent','em')+'</h2>'+t('globalText','p')+t('globalHistory','p','history')+'</div><div class="reveal"><div class="language-grid">'+''.join('<div class="language-tile"><span aria-hidden="true">'+x+'</span>'+arr('languages.'+str(i),HOME['languages'][i],'strong')+'</div>' for i,x in enumerate(['ع','En','Ру']))+'</div>'+t('location','p','global-location')+t('internationalNote','p','fineprint')+'</div></div></section>'
def platforms():
 links=dict(DATA['platforms']);links.update({'GitHub':'https://github.com/Enigma7979','Notion':NOTION,'Facebook':'https://www.facebook.com/AliAlkhuzaeeStartups?'})
 return '<section class="section platform-section" id="connect"><div class="shell">'+t('platforms','h2')+t('platformIntro','p','section-intro')+'<div class="platform-grid">'+''.join(f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer"><span>{e(name)}</span><span aria-hidden="true">↗</span></a>' for name,url in links.items())+'</div></div></section>'
def contact():
 cards=[]
 for country,num,phone,wa in [('belgium','+32 467 68 52 50','32467685250','personalWhatsApp'),('ukraine','+380 63 717 17 71','380637171771','businessWhatsApp')]:
  cards.append('<article class="contact-card"><h3 id="contact-'+country+'">'+t(country)+'</h3><p class="contact-number" dir="ltr">'+num+'</p><div class="contact-card-actions"><a href="tel:+'+phone+'" aria-labelledby="contact-'+country+' call-'+country+'"><span id="call-'+country+'" data-i18n="directCall">Direct Call</span><span aria-hidden="true">↗</span></a><a href="https://wa.me/'+phone+'" target="_blank" rel="noopener noreferrer">'+t(wa)+'<span aria-hidden="true">↗</span></a></div>'+('<details class="other-messaging"><summary>'+t('otherMessagingApps')+'<span aria-hidden="true">+</span></summary>'+t('otherMessaging','p')+'</details>' if country=='ukraine' else '')+'</article>')
 return '<section class="section contact-section" id="contact"><div class="shell contact-grid"><div class="reveal">'+t('contactLabel','p','eyebrow')+'<h2>'+t('contactTitle')+t('contactAccent','em')+'</h2>'+t('contactText','p','section-intro')+f'<a class="email-link" href="{MAIL}">'+t('businessEmail','small')+'<span dir="ltr">ali@alialkhuzaee.com <b aria-hidden="true">↗</b></span></a></div><div class="contact-cards reveal">'+''.join(cards)+'</div></div></section>'
def footer():return '<footer class="site-footer"><div class="shell"><div class="footer-top"><a class="footer-brand" href="/" data-language-route>ALI<br>ALKHUZAEE<span aria-hidden="true">✦</span></a><div>'+t('footer','p')+t('location','p','fineprint')+'</div></div><div class="footer-bottom"><span>© <span id="year">2026</span> Ali Alkhuzaee</span><a href="/media-kit/" data-language-route>'+t('mediaKit')+'</a><a href="/products/" data-language-route>'+t('navProducts')+'</a><a href="#top">'+t('back')+' ↑</a></div></div></footer>'
def head(kit):
 path='/media-kit/' if kit else '/';title='Media Kit | Ali Alkhuzaee — Brand Partnerships' if kit else 'Ali Alkhuzaee | Technology, Made Human.';desc=HOME['seoKit' if kit else 'seoHome']
 seo={'@context':'https://schema.org','@type':'Person','name':'Ali Alkhuzaee','url':'https://alialkhuzaee.com/','image':'https://alialkhuzaee.com/assets/portraits/ali-partnership-900.webp','email':'ali@alialkhuzaee.com','jobTitle':'AI & Technology Content Creator, N8N Automation Engineer','knowsLanguage':['Arabic','English','Russian'],'sameAs':list(DATA['platforms'].values())}
 return '<!doctype html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111d35"><title>'+title+'</title><meta name="description" content="'+e(desc)+'"><link rel="canonical" href="https://alialkhuzaee.com'+path+'">'+''.join(f'<link rel="alternate" hreflang="{lang}" href="https://alialkhuzaee.com{path}'+('' if lang=='x-default' else '?lang='+lang)+'">' for lang in ['en','ar','ru','x-default'])+'<meta property="og:type" content="website"><meta property="og:title" content="'+e(title)+'"><meta property="og:description" content="'+e(desc)+'"><meta property="og:url" content="https://alialkhuzaee.com'+path+'"><meta property="og:image" content="https://alialkhuzaee.com/assets/portraits/originals/partnership-original.jpeg"><meta name="twitter:card" content="summary_large_image"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Cairo:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="preload" as="image" href="/assets/portraits/'+('ali-partnership-900.webp' if kit else 'ali-hero-690.webp')+'"><link rel="stylesheet" href="/assets/site.css?v=short-2"><script src="/assets/site.js?v=short-1" defer></script><script type="application/ld+json">'+json.dumps(seo,ensure_ascii=False)+'</script></head><body id="top" data-page="'+('kit' if kit else 'home')+'"><a class="skip-link" href="#main" data-i18n="skip">Skip to content</a><div class="progress" aria-hidden="true"></div>'
def hero(kit):
 if kit:
  content=t('eyebrow','p','eyebrow',True)+'<h1>'+t('hero',kit=True)+t('name','em',kit=True)+'</h1>'+t('intro','p','hero-intro',True)+'<div class="hero-buttons">'+button('cta',MAIL,kit=True)+button('pdf','/media-kit/Ali-Alkhuzaee-Media-Kit.pdf?v=premium-3','outline')+'</div>'+t('pdfNote','p','fineprint')
 else:content=t('heroEyebrow','p','eyebrow')+'<h1>'+t('heroLine1')+t('heroLine2','em')+'</h1>'+t('heroIntro','p','hero-intro')+'<div class="hero-buttons">'+button('explore','#work')+button('workWithMe','/media-kit/','outline',route=True)+'</div>'+t('heroNote','p','hero-note')
 return '<section class="hero '+('kit-hero' if kit else '')+'"><div class="hero-grid" aria-hidden="true"></div><div class="shell hero-layout"><div class="hero-content reveal">'+content+'</div><div class="hero-visual">'+orb()+'<div class="portrait-stage">'+picture('kit' if kit else 'hero')+'</div><div class="portrait-note"><span>ALI ALKHUZAEE</span>'+t('credential','small')+'</div><div class="visual-tag"><span aria-hidden="true">✦</span> AI / AUTOMATION</div></div></div><div class="hero-bottom shell">'+t('location','p')+'<a href="#'+('why' if kit else 'about')+'">'+t('scroll')+' ↓</a></div></section>'
def about():return '<section class="section paper" id="about"><div class="shell about-layout"><div class="reveal">'+t('aboutLabel','p','eyebrow')+'<h2>'+t('aboutTitle')+t('aboutAccent','em')+'</h2></div><div class="about-copy reveal">'+t('aboutText','p')+t('aboutText2','p')+'<div class="credentials">'+t('credential')+t('founder')+'</div></div></div></section>'
def expertise():return '<section class="section navy" id="expertise"><div class="shell">'+sectionhead('expertiseLabel','expertiseTitle','expertiseAccent','expertiseIntro')+'<div class="expertise-grid">'+''.join('<article class="expertise-card reveal"><span class="cap-icon" aria-hidden="true">'+icon+'</span>'+arr(f'expertiseCards.{i}.0',item[0],'h3')+arr(f'expertiseCards.{i}.1',item[1],'p')+'</article>' for i,(item,icon) in enumerate(zip(HOME['expertiseCards'],['✳','⌘','↗'])))+'</div></div></section>'
def projects():return '<section class="section project-section" id="projects"><div class="shell">'+sectionhead('projectsLabel','projectsTitle','projectsAccent','projectsIntro')+'<div class="project-grid"><article class="project-card automation-card reveal"><div class="workflow-art" aria-hidden="true"><span>INPUT</span><i></i><b>n8n</b><i></i><span>ACTION</span></div>'+t('automationTitle','h3')+t('automationText','p')+'<div class="project-links">'+button('notion',NOTION,'text')+button('github','https://github.com/Enigma7979','text')+'</div></article><article class="project-card education-card reveal"><span class="project-wordmark">STUDY UA PLUS<span>YOUR WAY ABROAD</span></span><h3>Study UA Plus</h3>'+t('studyText','p')+'<div class="project-links">'+button('studyLink','https://studyua.org/','text')+'</div></article></div></div></section>'
def partner():return '<section class="section partner-band"><div class="shell partner-layout"><div class="reveal">'+t('partnerLabel','p','eyebrow')+'<h2>'+t('partnerTitle')+t('partnerAccent','em')+'</h2>'+t('partnerText','p')+button('partnerCta','/media-kit/','white',route=True)+'</div><div class="partner-symbol" aria-hidden="true">✦</div></div></section>'
def why():return '<section class="section paper" id="why"><div class="shell">'+sectionhead('whyLabel','why',intro='whyIntro',kit=True)+'<div class="why-grid">'+''.join('<article class="why-card reveal"><span class="card-number">0'+str(i+1)+'</span>'+arr(f'whyCards.{i}.0',item[0],'h3')+arr(f'whyCards.{i}.1',item[1],'p')+'</article>' for i,item in enumerate(KIT['whyCards']))+'</div></div></section>'
def formats():return '<section class="section navy" id="collaborations"><div class="shell">'+sectionhead('formatsLabel','formatsTitle',intro='formatsIntro',kit=True)+'<div class="formats-grid">'+''.join('<article class="format-card reveal"><span class="card-number">0'+str(i+1)+'</span>'+arr(f'formats.{i}.0',item[0],'h3')+arr(f'formats.{i}.1',item[1],'p')+'</article>' for i,item in enumerate(KIT['formats']))+'</div></div></section>'
def metrics():return '<section class="section paper" id="audience" hidden><div class="shell">'+sectionhead('statsLabel','statsTitle',intro='statsIntro',kit=True)+'<div class="metrics-grid" id="metrics"></div></div></section>'
def build():
 for kit in [False,True]:
  body=head(kit)+nav(kit)+'<main id="main">'+hero(kit)
  body+='<div class="discipline-strip" aria-hidden="true"><span>AI & TECHNOLOGY</span><b>✳</b><span>AUTOMATION</span><b>✳</b><span>CREATOR STORYTELLING</span></div>'
  body+=(why()+formats()+videos()+metrics()+international()+platforms() if kit else about()+expertise()+videos()+projects()+international()+partner()+platforms())
  body+=contact()+'</main>'+footer()+'</body></html>\n'
  (ROOT/('media-kit/index.html' if kit else 'index.html')).write_text(body)
if __name__=='__main__':build()
